query CashflowSummary($filter: TransactionFilter!, $granularity: Granularity!) {
  cashflowSummary(filter: $filter, granularity: $granularity) {
    buckets {
      start
      end
      income
      spending
      net
      transactionCount
    }
    total {
      income
      spending
      net
      transactionCount
    }
    currency
  }
}
